import { mkdtempSync, renameSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { afterEach, describe, expect, it } from 'vitest';
import { writeFiles } from '../git/test-support/fixture-files.mjs';
import { fingerprintPackageCode } from './code-fingerprint.mjs';
import { createFindingsCache } from './findings-cache.mjs';

const roots = [];

afterEach(() => {
  for (const root of roots.splice(0)) rmSync(root, { recursive: true, force: true });
});

function packageRoot() {
  const root = mkdtempSync(path.join(tmpdir(), 'nitpicker-code-fingerprint-'));
  roots.push(root);
  writeFiles(root, {
    'package.json': '{"name":"nitpicker","version":"1"}',
    'core/runner.mjs': 'export const version = 1;',
    'shared/rules.mjs': 'export const rules = [];',
    'languages/typescript/rules.mjs': 'export const rules = [];',
  });
  return root;
}

describe('package code fingerprint', () => {
  it.each([
    'package.json',
    'core/runner.mjs',
    'shared/rules.mjs',
    'languages/typescript/rules.mjs',
    'languages/python/rules.py',
    'languages/java/Rules.java',
    'languages/java/Rules.kt',
    'languages/java/rules.xml',
    'languages/typescript/defaults/rules.json',
  ])('invalidates cached findings after %s changes without an analyzer version bump', (file) => {
    const root = packageRoot();
    const options = {
      directory: path.join(root, 'cache'),
      mergeBaseSha: 'abc',
      projectRelativePath: '.',
    };
    const analyzer = { name: 'rules', version: '1', configurationHash: 'same-policy' };
    const before = createFindingsCache({
      ...options,
      codeFingerprint: fingerprintPackageCode(root),
    });
    before.write(analyzer, { findings: [] });
    expect(before.read(analyzer)).toEqual({ findings: [] });

    writeFiles(root, { [file]: 'changed rule set' });
    const after = createFindingsCache({
      ...options,
      codeFingerprint: fingerprintPackageCode(root),
    });

    expect(after.read(analyzer)).toBeUndefined();
  });

  it('ignores tests, fixtures and generated bytecode absent from the shipped package', () => {
    const root = packageRoot();
    const before = fingerprintPackageCode(root);

    writeFiles(root, {
      'core/runner.test.mjs': 'test code',
      'shared/fixtures/rule.mjs': 'fixture code',
      'languages/python/test-support/helper.py': 'helper code',
      'languages/java/__tests__/Rules.java': 'test code',
      'languages/python/__pycache__/rules.pyc': 'bytecode',
      'languages/python/rules.pyc': 'bytecode',
      'languages/typescript/README.md': 'documentation',
      'core/notes.txt': 'not shipped',
    });

    expect(fingerprintPackageCode(root)).toBe(before);
  });

  it('depends on relative file names and content, not the installation directory', () => {
    const root = packageRoot();
    const before = fingerprintPackageCode(root);
    const relocated = path.join(root, 'relocated');
    writeFiles(relocated, {
      'package.json': '{"name":"nitpicker","version":"1"}',
      'core/runner.mjs': 'export const version = 1;',
      'shared/rules.mjs': 'export const rules = [];',
      'languages/typescript/rules.mjs': 'export const rules = [];',
    });
    expect(fingerprintPackageCode(relocated)).toBe(before);

    renameSync(
      path.join(relocated, 'shared/rules.mjs'),
      path.join(relocated, 'shared/renamed.mjs'),
    );
    expect(fingerprintPackageCode(relocated)).not.toBe(before);
  });
});
